// A stand-in written for this fixture, not the published bytes of @solidjs/web@2.0.0-rc.21 `dist/web.js` (the dialect answers by the module the build resolves to, and
// the runtime's own files are not read). `addEvent` here registers what it is handed, as the real one does.
export function addEvent(node, name, handler) {
  node.addEventListener(name, handler);
}
